"""Original infectious endocarditis and bacteremia: diagnostic half."""
from qbank_authoring import question,ref,finalize
EC=ref('ESC Guidelines for the Management of Endocarditis, 2023','https://academic.oup.com/eurheartj/article/44/39/3948/7243107')
DU=ref('Duke-ISCVID Criteria for Infective Endocarditis, 2023','https://academic.oup.com/cid/article/77/4/518/7151107')
SA=ref('IDSA/ESCMID Consensus Statements on S. aureus Bacteremia, September 2026','https://www.idsociety.org/practice-guideline/staphylococcus-aureus-bacteremia')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient has persistent fever, repeated typical-organism blood cultures and a new regurgitant murmur. What is the best next cardiac investigation pathway?', 'Prompt echocardiography, usually TTE initially with TEE according to risk, findings and image quality',[
 ('Exclude endocarditis if the murmur is not loud','Murmur intensity does not exclude destructive valve infection.'),('Use ECG alone to exclude vegetations','ECG does not visualize valve lesions.'),('Wait until antibiotics are completed before cardiac imaging','Early imaging affects diagnosis and management.')],
 'Bloodstream and valve findings require a coordinated endocarditis assessment', '**Echocardiography evaluates vegetations, regurgitation and complications.**',['TEE is especially important for prosthetic material or suspected extension.','Blood cultures should be obtained promptly before therapy when safely feasible.'], '**Use an endocarditis team for complex decisions.**',['Negative initial imaging does not end a high-probability investigation.','Assess heart failure, embolism and uncontrolled infection.'],[['TTE','Initial structural assessment'],['TEE','Higher-resolution and prosthetic/complication assessment'],['Integration','Cultures and clinical findings']],[EC],style='clinical_scenario')
q('Clinical suspicion of endocarditis remains high despite an initially negative echocardiographic study. Which principle is appropriate?', 'Repeat appropriate echocardiography, commonly within five to seven days or sooner if the clinical situation warrants',[
 ('A single negative study permanently excludes infection','Early or small lesions can be missed.'),('Stop all microbiological investigation because imaging is negative','Diagnostic modalities are complementary.'),('Repeat only after a new embolic stroke has occurred','Waiting for a complication is inappropriate.')],
 'Valve infection evolves and early imaging has limitations', '**Repeat imaging can reveal previously occult lesions.**',['TEE may be required after a nondiagnostic TTE.','CT or nuclear imaging can add information in selected settings.'], '**Let clinical deterioration accelerate reassessment.**',['New conduction changes or heart failure require urgent review.','Continue source and pathogen evaluation in parallel.'],[['Initial negative','Not universal exclusion'],['Persistent suspicion','Repeat or complementary imaging'],['Deterioration','Urgent reassessment']],[EC])
q('A patient with aortic-valve endocarditis develops a new prolonged PR interval and AV block. What complication is most concerning?', 'Perivalvular extension with an aortic-root abscess',[
 ('A benign expected antibiotic effect requiring no review','New conduction disease is a warning sign.'),('An isolated tricuspid vegetation as the most direct mechanism','The conduction system is anatomically close to the aortic root.'),('Proof that the infection has already healed','It can indicate extension and worsening.')],
 'Electrical changes can reveal anatomical spread', '**Aortic-root infection can involve tissue near the conduction system.**',['Abscess, fistula and prosthetic dehiscence are serious complications.','TEE and cardiac CT may define the extent.'], '**Arrange urgent surgical-team evaluation.**',['Do not wait for completion of the antibiotic course if uncontrolled extension is present.','Monitor rhythm and hemodynamic status.'],[['New AV block','Possible perivalvular spread'],['Imaging','TEE and selected cardiac CT'],['Action','Urgent complication and surgical assessment']],[EC],style='clinical_scenario')
q('A person who injects drugs has S. aureus bacteremia and multiple peripheral cavitating pulmonary nodules. Which source is particularly likely?', 'Right-sided, especially tricuspid, infective endocarditis with septic pulmonary emboli',[
 ('An isolated left-sided valve lesion as the usual direct pulmonary embolic source','Left-sided emboli usually enter the systemic circulation.'),('Latent TB infection as the explanation for acute bacteremia','Latent TB does not cause this acute syndrome.'),('Noninfectious pulmonary thromboembolism as a complete explanation','Bacteremia and cavitating nodules suggest septic embolization.')],
 'Embolic destination helps localize the infected source', '**Right-sided vegetations can seed the pulmonary circulation.**',['Venous septic thrombophlebitis is another possible source.','Assess the tricuspid valve and other endovascular sites.'], '**Treat the bloodstream infection and its source.**',['Look for respiratory compromise and recurrent embolization.','Offer nonjudgmental addiction and harm-reduction support.'],[['Right-sided IE','Pulmonary septic emboli'],['Left-sided IE','Systemic embolic territory'],['Alternative source','Infected venous thrombus']],[EC],style='clinical_scenario')
q('Which additional evaluation is important in Streptococcus gallolyticus bacteremia or endocarditis?', 'Assessment for colorectal neoplasia',[
 ('Routine attribution to dental plaque without considering the bowel','The organism has an important colorectal association.'),('Exclusion of all gastrointestinal disease after one normal hemoglobin result','Neoplasia can be present without anemia.'),('Treating the blood isolate as invariably a contaminant','It can represent clinically significant bacteremia or IE.')],
 'The pathogen can identify an associated underlying disease', '**S. gallolyticus has a recognized association with colorectal lesions.**',['Evaluate both the endovascular infection and the possible gastrointestinal source.','The exact assessment is coordinated with clinical stability.'], '**Do not let infection treatment displace appropriate follow-up.**',['Arrange colon evaluation according to the care pathway.','Document findings and the need for surveillance.'],[['Organism','S. gallolyticus'],['Association','Colorectal neoplasia'],['Care','Treat infection and investigate the association']],[EC])
q('What is a common reason for culture-negative endocarditis?', 'Antibiotics administered before blood cultures were obtained',[
 ('All endocarditis pathogens are unculturable','Many common organisms grow in routine cultures.'),('The absence of fever always prevents organism growth','Temperature is not that determinant of culture recovery.'),('Every negative culture establishes nonbacterial thrombotic endocarditis','Prior therapy and fastidious organisms must be considered.')],
 'Culture negativity has several mechanisms', '**Prior antimicrobial exposure can suppress viable-organism recovery.**',['Fastidious organisms need targeted testing.','Noninfectious valve lesions also enter the differential.'], '**Review the treatment and exposure history.**',['Coordinate additional serology, molecular tests and tissue studies when appropriate.','Do not withhold urgent therapy in an unstable patient solely to improve culture yield.'],[['Prior antibiotics','Common reason'],['Fastidious organisms','Need targeted methods'],['Alternative diagnosis','Consider with the full evidence']],[EC,DU])
q('A livestock-exposed patient has culture-negative endocarditis and a high phase-I IgG response to Coxiella burnetii. What is most likely?', 'Q-fever endocarditis',[
 ('Acute uncomplicated Q fever without focal infection solely because antibodies are present','The endocarditis context and phase-I response suggest persistent focal disease.'),('Bartonella endocarditis as established by Coxiella-specific serology','These are distinct organisms and tests.'),('A routine contaminant requiring no assessment','Coxiella is an important culture-negative IE cause.')],
 'Targeted serology can identify a fastidious endocarditis pathogen', '**Coxiella requires specialized diagnostic interpretation.**',['The 2023 Duke-ISCVID framework incorporates appropriate Coxiella evidence.','Exposure history and valve risk help interpret probability.'], '**Use organism-specific specialist treatment.**',['Treatment differs substantially from ordinary short-course bacteremia care.','Assess other persistent focal sites when clinically indicated.'],[['Exposure','Livestock-related aerosols'],['Laboratory clue','Phase-I IgG response'],['Syndrome','Persistent focal infection/endocarditis']],[DU,EC],style='clinical_scenario')
q('Culture-negative endocarditis occurs in a patient with body-louse exposure and unstable housing. Which organism is particularly relevant?', 'Bartonella quintana',[
 ('Bartonella henselae as the organism most specifically linked to body lice','Cat exposure is more characteristic for B. henselae.'),('Streptococcus gallolyticus as the classic body-louse organism','Its better-known association is colorectal disease.'),('Candida auris as the characteristic louse-transmitted bacterium','It is a yeast with different epidemiology.')],
 'A careful social and exposure history directs specialized testing', '**B. quintana can cause culture-negative IE.**',['Serology and molecular testing may be needed.','Cross-reactivity and test interpretation require laboratory expertise.'], '**Treat the person and exposure context together.**',['Address ectoparasite control and access barriers.','Use an organism-specific antimicrobial plan.'],[['B. quintana','Body-louse association'],['B. henselae','Cat association'],['Diagnosis','Targeted serology/molecular evidence']],[DU,EC],style='clinical_scenario')
q('Which diagnostic development is included in the 2023 Duke-ISCVID framework?', 'Selected molecular and advanced-imaging evidence can contribute to major criteria under defined conditions',[
 ('Only a new murmur can ever qualify as a major criterion','The framework includes microbiology and imaging evidence.'),('Any positive PCR from any body site automatically proves definite IE','Organism, sample and criterion conditions matter.'),('Any FDG uptake anywhere is sufficient for definite IE','Interpretation is location- and context-specific.')],
 'Modern criteria incorporate evidence beyond routine cultures and TTE', '**Specific blood molecular results and appropriate cardiac imaging can be important.**',['Coxiella, Bartonella and T. whipplei have defined molecular roles.','Prosthetic-material imaging requires careful interpretation.'], '**Use the exact criterion definitions.**',['Criteria support consistent diagnosis but do not replace clinical judgment.','Avoid treating a single nonspecific finding as definitive.'],[['Microbiology','Defined culture/serology/molecular evidence'],['Imaging','Defined cardiac involvement'],['Interpretation','Whole clinical framework']],[DU])
q('A patient with metastatic adenocarcinoma has systemic emboli and sterile valve vegetations after a thorough negative infection assessment. Which diagnosis should be considered?', 'Nonbacterial thrombotic endocarditis',[
 ('IE is proven solely because a vegetation is present','Vegetations can be noninfectious.'),('A positive D-dimer alone identifies the valve pathogen','D-dimer is not microbiological evidence.'),('A normal temperature excludes every valve lesion','Noninfectious vegetations may occur without fever.')],
 'A valve mass is not synonymous with active infection', '**Malignancy and autoimmune states can be associated with sterile thrombotic vegetations.**',['Culture-negative infection must still be investigated appropriately.','Embolic events can be the presenting problem.'], '**Manage the underlying condition and embolic risk through a specialist plan.**',['Anticoagulation decisions require individual assessment.','Avoid committing to prolonged antibiotics without supporting evidence.'],[['NBTE','Sterile thrombotic lesion'],['Association','Malignancy or autoimmune disease'],['Key differential','Culture-negative IE']],[EC],style='clinical_scenario')
q('What follow-up culture strategy does the 2026 IDSA/ESCMID adult SAB consensus suggest?', 'At least two sets at 48 hours after the first positive sample, then one or two sets every 24–48 hours until clearance',[
 ('No repeat cultures once fever improves','Clinical improvement does not document bloodstream clearance.'),('A single repeat after the entire course is finished','This misses persistent bacteremia during treatment.'),('Only repeat if the initial organism is MRSA','Follow-up is relevant to MSSA as well.')],
 'Documented clearance is a key management milestone', '**Persistent positivity at or beyond 48 hours prompts further source evaluation.**',['The strategy can be intensified in higher-risk cases.','Adequate collection and interpretation remain important.'], '**Use clearance and source control in duration planning.**',['The clearance date commonly anchors treatment counting.','A later source-removal date can affect that anchor in selected cases.'],[['Initial follow-up','Two sets at 48 hours'],['Then','Every 24–48 hours until negative'],['Persistent positivity','Reassess deep foci and source control']],[SA])
q('Under the 2026 IDSA/ESCMID consensus, what is the usual initial echocardiographic approach for an adult with S. aureus bacteremia?', 'Routinely perform TTE, then select TEE according to risk and findings',[
 ('Omit all echocardiography if no murmur is heard','Occult IE can be present without a murmur.'),('TEE is forbidden whenever the TTE is negative','High-risk features can warrant TEE despite negative TTE.'),('Use the same no-imaging rule for every adult and child','Age and clinical context differ in the recommendations.')],
 'S. aureus bacteremia has an important endocarditis risk', '**Routine TTE is suggested for adults.**',['Prosthetic material, persistent cultures, emboli and other features increase the value of TEE.','A low-risk adult with a good-quality negative TTE may not need TEE.'], '**Use a risk-informed rather than automatic all-or-none strategy.**',['Reassess if new findings appear.','Infectious-disease consultation is strongly encouraged.'],[['Adult initial test','TTE'],['TEE','Risk- and finding-based'],['Ongoing care','Repeat clinical assessment']],[SA])
q('How does the 2026 IDSA/ESCMID consensus frame S. aureus bacteremia risk?', 'As a dynamic assessment leading to a precise diagnosis with or without deep-seated or metastatic infection',[
 ('A permanent label assigned solely from the first day’s fever','Risk changes as information and the clinical course evolve.'),('Every risk factor is equivalent to a confirmed metastatic focus','Risk does not establish the actual diagnosis.'),('Absence of focal symptoms on admission excludes later metastatic infection','Occult foci can become apparent later.')],
 'Risk stratification guides the intensity of investigation', '**Community onset, persistent cultures and intracardiac devices are key risk factors.**',['Other clinical features also matter.','A higher-risk patient needs tailored evaluation rather than automatic assumptions.'], '**Reclassify when new evidence appears.**',['Confirm actual foci to guide source control and treatment duration.','Avoid both missed infection and unnecessarily prolonged therapy.'],[['Risk','Guides evaluation'],['Diagnosis','Defines actual focus'],['Course','Requires ongoing reassessment']],[SA])
q('A patient with S. aureus bacteremia develops focal severe back pain. Which investigation is most directly indicated?', 'Targeted spinal MRI for vertebral infection or epidural involvement',[
 ('No imaging because the bloodstream organism is already known','A metastatic focus changes management.'),('A normal plain radiograph as definitive exclusion','Early spinal infection can be radiographically occult.'),('Routine brain CT as a substitute for spinal assessment','It does not evaluate the symptomatic site.')],
 'A new localized symptom can reveal a metastatic focus', '**SAB can seed vertebrae, discs and epidural tissues.**',['Neurological deficits increase urgency.','An identified deep focus changes treatment and source-control planning.'], '**Perform symptom-directed evaluation rather than relying only on whole-body screening.**',['Assess weakness and sphincter symptoms.','Involve spine specialists promptly when compression or instability is possible.'],[['Symptom','Focal back pain'],['Concern','Vertebral/epidural infection'],['Test','Targeted MRI']],[SA],style='clinical_scenario')

